function validate([pairs]) {
  if (!Array.isArray(pairs) || pairs.length < 1 || pairs.length > 100000) return 'pairs needs 1 to 100000 pairs.';
  const seen = new Set();
  for (const pair of pairs) {
    if (!Array.isArray(pair) || pair.length !== 2 || !pair.every(Number.isInteger)) return 'Each pair is two integers [x, y].';
    const [x, y] = pair;
    if (x < 1 || y > 500 || x >= y) return 'Each pair needs 1 <= x < y <= 500.';
    const key = x * 1000 + y;
    if (seen.has(key)) return 'Pairs must be distinct.';
    seen.add(key);
  }
  return null;
}

