function checkWays(pairs) {
  const neighbors = new Map();
  for (const [x, y] of pairs) {
    if (!neighbors.has(x)) neighbors.set(x, new Set());
    if (!neighbors.has(y)) neighbors.set(y, new Set());
    neighbors.get(x).add(y);
    neighbors.get(y).add(x);
  }
  const nodeCount = neighbors.size;

  let root = -1;
  for (const [node, near] of neighbors) {
    if (near.size === nodeCount - 1) {
      root = node;
      break;
    }
  }
  if (root === -1) {
    return 0;
  }

  let ways = 1;
  for (const [node, near] of neighbors) {
    if (node === root) {
      continue;
    }
    let parent = -1;
    let parentDegree = Infinity;
    for (const other of near) {
      const degree = neighbors.get(other).size;
      if (degree >= near.size && degree < parentDegree) {
        parent = other;
        parentDegree = degree;
      }
    }
    if (parent === -1) {
      return 0;
    }
    const parentNear = neighbors.get(parent);
    for (const other of near) {
      if (other !== parent && !parentNear.has(other)) {
        return 0;
      }
    }
    if (parentDegree === near.size) {
      ways = 2;
    }
  }
  return ways;
}

