function checkWays(pairs) {
  // Try every parent assignment (0 = no parent) and count the trees whose ancestor pairs equal the input.
  const nodes = [...new Set(pairs.flat())];
  const want = new Set(pairs.map(([x, y]) => x + ',' + y));
  const adjacent = new Map(nodes.map(v => [v, [0]]));
  for (const [x, y] of pairs) { adjacent.get(x).push(y); adjacent.get(y).push(x); }
  const parent = new Map();
  let found = 0;
  const valid = () => {
    if (nodes.filter(v => parent.get(v) === 0).length !== 1) return false;
    const got = new Set();
    for (const v of nodes) {
      let u = parent.get(v), steps = 0;
      while (u !== 0) {
        if (++steps > nodes.length) return false;
        got.add(Math.min(u, v) + ',' + Math.max(u, v));
        u = parent.get(u);
      }
    }
    return got.size === want.size && [...got].every(p => want.has(p));
  };
  const choose = (i) => {
    if (found >= 2) return;
    if (i === nodes.length) { if (valid()) found++; return; }
    for (const p of adjacent.get(nodes[i])) { parent.set(nodes[i], p); choose(i + 1); }
  };
  choose(0);
  return found;
}

