function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const shuffle = (list) => { for (let i = list.length - 1; i > 0; i--) { const j = pick(i + 1); [list[i], list[j]] = [list[j], list[i]]; } return list; };
  const small = size === 'small';
  const labels = shuffle(Array.from({ length: small && rand() < 0.7 ? 9 : 500 }, (_, i) => i + 1));
  const count = small ? 2 + pick(5) : 150 + pick(201);
  const maxDepth = 5;
  const mode = pick(small ? 4 : 3);
  const sorted = (a, b) => (a < b ? [a, b] : [b, a]);
  let pairs = [];
  if (mode === 3) {
    // A random set of pairs that need not come from any tree.
    const keep = 0.3 + rand() * 0.5;
    for (let i = 0; i < count; i++) for (let j = i + 1; j < count; j++) if (rand() < keep) pairs.push(sorted(labels[i], labels[j]));
    if (!pairs.length) pairs.push(sorted(labels[0], labels[1]));
    return [shuffle(pairs)];
  }
  const parent = [-1], depth = [0];
  if (mode === 1) {
    // Every inner node gets at least two children, so the tree is the only answer.
    const queue = [0];
    while (queue.length && parent.length < count) {
      const v = queue.shift();
      const remaining = count - parent.length;
      if (depth[v] >= maxDepth || remaining < 2 || (queue.length > 0 && rand() < 0.3)) continue;
      const children = 2 + pick(Math.min(3, remaining - 1));
      for (let c = 0; c < children; c++) { queue.push(parent.length); parent.push(v); depth.push(depth[v] + 1); }
    }
  }
  if (parent.length === 1) {
    for (let i = 1; i < count; i++) {
      let p = pick(i);
      while (depth[p] >= maxDepth) p = pick(i);
      parent.push(p); depth.push(depth[p] + 1);
    }
  }
  const present = new Set();
  for (let v = 1; v < parent.length; v++) {
    for (let a = parent[v]; a !== -1; a = parent[a]) { const pair = sorted(labels[a], labels[v]); pairs.push(pair); present.add(pair.join()); }
  }
  if (mode === 2) {
    if (rand() < 0.5 && pairs.length > 1) pairs.splice(pick(pairs.length), 1);
    else {
      for (let tries = 0; tries < 50; tries++) {
        const pair = sorted(labels[pick(parent.length)], labels[pick(parent.length)]);
        if (pair[0] !== pair[1] && !present.has(pair.join())) { pairs.push(pair); break; }
      }
    }
  }
  return [shuffle(pairs)];
}
